import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { EventEmitter } from 'events';
import {
  mkdtempSync,
  mkdirSync,
  rmSync,
  existsSync,
  utimesSync,
  writeFileSync,
  chmodSync,
  readFileSync,
} from 'fs';
import { spawn as spawnProcess } from 'child_process';
import { tmpdir } from 'os';
import { dirname, join } from 'path';
import { fileURLToPath } from 'url';
import {
  acquireInstallLock,
  releaseInstallLock,
  runNpmInstall,
} from '../cli/install-runner.js';

const REPO_ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const WRAPPER_PATH = join(REPO_ROOT, 'cli', 'mcp-server-wrapper.js');

function makeFakeChild(pid = 999999999): any {
  const child: any = new EventEmitter();
  child.pid = pid;
  child.stdout = new EventEmitter();
  child.stderr = new EventEmitter();
  child.kill = vi.fn();
  return child;
}

describe('install-runner — install lock (#161)', () => {
  let root: string;

  beforeEach(() => {
    root = mkdtempSync(join(tmpdir(), 'episodic-memory-install-lock-'));
  });

  afterEach(() => {
    try { rmSync(root, { recursive: true, force: true }); } catch {}
  });

  it('a second acquire is excluded while the lock is held; re-acquiring works after release', () => {
    const first = acquireInstallLock(root);
    expect(first).not.toBeNull();

    const second = acquireInstallLock(root);
    expect(second).toBeNull();

    releaseInstallLock(first!);

    const third = acquireInstallLock(root);
    expect(third).not.toBeNull();
    releaseInstallLock(third!);
  });

  it('steals a stale lock past the threshold but leaves a fresh one alone', () => {
    const staleMs = 200;
    const lockPath = join(root, '.episodic-memory-install.lock');
    mkdirSync(lockPath);

    // Fresh lock (mtime = now): must NOT be stolen.
    expect(acquireInstallLock(root, { staleMs })).toBeNull();

    // Age the lock dir's mtime past the threshold: now it's stealable.
    const ancient = new Date(Date.now() - staleMs - 1000);
    utimesSync(lockPath, ancient, ancient);
    const stolen = acquireInstallLock(root, { staleMs });
    expect(stolen).not.toBeNull();
    releaseInstallLock(stolen!);
  });
});

describe('install-runner — runNpmInstall termination handling (#161)', () => {
  let root: string;

  beforeEach(() => {
    root = mkdtempSync(join(tmpdir(), 'episodic-memory-install-runner-'));
  });

  afterEach(() => {
    try { rmSync(root, { recursive: true, force: true }); } catch {}
  });

  it('terminate() kills the injected child and releases the lock, and leaves no listener leak after the child later reports exit', async () => {
    const beforeSigterm = process.listenerCount('SIGTERM');
    const beforeSigint = process.listenerCount('SIGINT');
    const beforeSighup = process.listenerCount('SIGHUP');
    const beforeExit = process.listenerCount('exit');

    const child = makeFakeChild();
    const fakeSpawn = vi.fn(() => child);
    const lock = acquireInstallLock(root);
    expect(lock).not.toBeNull();

    const install = runNpmInstall(root, { spawn: fakeSpawn, lockHandle: lock });

    // Handlers registered for the duration of the install.
    expect(process.listenerCount('SIGTERM')).toBe(beforeSigterm + 1);

    // Invoke the termination/cleanup path directly — no real signal sent to
    // this test process.
    install.terminate();

    expect(child.kill).toHaveBeenCalled();
    expect(existsSync(join(root, '.episodic-memory-install.lock'))).toBe(false);

    // A moment later the (killed) child reports its actual exit. The exit
    // handler must not re-add or double-remove listeners.
    child.emit('exit', null);
    await install.promise.catch(() => {}); // terminate path may resolve or reject; only care about listener cleanup here

    expect(process.listenerCount('SIGTERM')).toBe(beforeSigterm);
    expect(process.listenerCount('SIGINT')).toBe(beforeSigint);
    expect(process.listenerCount('SIGHUP')).toBe(beforeSighup);
    expect(process.listenerCount('exit')).toBe(beforeExit);
  });

  it('resolves and removes handlers when the child exits 0 normally (no termination)', async () => {
    const beforeSigterm = process.listenerCount('SIGTERM');

    const child = makeFakeChild();
    const fakeSpawn = vi.fn(() => child);
    const install = runNpmInstall(root, { spawn: fakeSpawn });

    expect(process.listenerCount('SIGTERM')).toBe(beforeSigterm + 1);

    child.emit('exit', 0);
    await expect(install.promise).resolves.toBeUndefined();

    expect(child.kill).not.toHaveBeenCalled();
    expect(process.listenerCount('SIGTERM')).toBe(beforeSigterm);
  });

  it('rejects when the child exits non-zero, and still removes handlers', async () => {
    const beforeSigterm = process.listenerCount('SIGTERM');

    const child = makeFakeChild();
    const fakeSpawn = vi.fn(() => child);
    const install = runNpmInstall(root, { spawn: fakeSpawn });

    child.emit('exit', 1);
    await expect(install.promise).rejects.toThrow(/npm install failed/);

    expect(process.listenerCount('SIGTERM')).toBe(beforeSigterm);
  });
});

describe('mcp-server-wrapper — real spawn, orphan prevention on SIGTERM (#161)', () => {
  let root: string;
  let binDir: string;

  beforeEach(() => {
    root = mkdtempSync(join(tmpdir(), 'episodic-memory-wrapper-root-'));
    binDir = mkdtempSync(join(tmpdir(), 'episodic-memory-wrapper-bin-'));
  });

  afterEach(() => {
    try { rmSync(root, { recursive: true, force: true }); } catch {}
    try { rmSync(binDir, { recursive: true, force: true }); } catch {}
  });

  it('kills the stub npm install child when the wrapper is SIGTERM-ed mid-install', async () => {
    // A stub "npm" that just stays alive and records its own pid, so we can
    // tell whether the wrapper's real child-tree kill reaches it. No network
    // call is made — this never touches the real npm registry.
    const pidFile = join(root, 'npm-stub.pid');
    const npmStubPath = join(binDir, 'npm');
    writeFileSync(
      npmStubPath,
      `#!/usr/bin/env node\n` +
        `import { writeFileSync } from 'fs';\n` +
        `writeFileSync(${JSON.stringify(pidFile)}, String(process.pid));\n` +
        `setInterval(() => {}, 1000);\n`,
      'utf-8'
    );
    chmodSync(npmStubPath, 0o755);

    // An empty plugin root: node_modules is entirely absent, so the wrapper's
    // findMissingDeps probe reports everything missing and takes the install
    // path, invoking our stub "npm" (resolved via PATH, prepended below).
    const wrapper = spawnProcess(process.execPath, [WRAPPER_PATH], {
      cwd: root,
      env: {
        ...process.env,
        CLAUDE_PLUGIN_ROOT: root,
        PATH: `${binDir}${process.platform === 'win32' ? ';' : ':'}${process.env.PATH}`,
      },
      stdio: ['ignore', 'pipe', 'pipe'],
    });

    try {
      await waitFor(() => existsSync(pidFile), 10_000);
      const stubPid = parseInt(readFileSync(pidFile, 'utf-8').trim(), 10);
      expect(Number.isFinite(stubPid)).toBe(true);
      expect(isAlive(stubPid)).toBe(true);

      wrapper.kill('SIGTERM');

      await waitFor(() => !isAlive(stubPid), 10_000);
      expect(isAlive(stubPid)).toBe(false);
    } finally {
      try { wrapper.kill('SIGKILL'); } catch {}
    }
  }, 20_000);
});

function isAlive(pid: number): boolean {
  try {
    process.kill(pid, 0);
    return true;
  } catch {
    return false;
  }
}

async function waitFor(condition: () => boolean, timeoutMs: number): Promise<void> {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    if (condition()) return;
    await new Promise((resolve) => setTimeout(resolve, 50));
  }
  if (!condition()) {
    throw new Error(`waitFor: condition not met within ${timeoutMs}ms`);
  }
}

import { mkdtempSync } from 'fs';
import { tmpdir } from 'os';
import { join } from 'path';

/**
 * Isolate every test run from the developer's real ~/.config/superpowers.
 * Without this, getSuperpowersDir()'s ensureDir side effect creates real dirs
 * (and sometimes a real db.sqlite) when EPISODIC_MEMORY_CONFIG_DIR is unset.
 * See https://github.com/obra/episodic-memory/issues/119
 */
const isolatedRoot = mkdtempSync(join(tmpdir(), 'episodic-memory-vitest-'));

process.env.EPISODIC_MEMORY_CONFIG_DIR = join(isolatedRoot, 'superpowers');
process.env.CLAUDE_CONFIG_DIR = join(isolatedRoot, 'claude');
process.env.CODEX_HOME = join(isolatedRoot, 'codex');

// Clear any ambient summarizer-billing signals so tests get deterministic
// cost-guard (#104) and timeout (#160) behavior regardless of the developer's
// shell. No test needs a real API key — they all mock the SDK query(). Tests
// that exercise the metered guard set these vars in their own bodies.
delete process.env.ANTHROPIC_API_KEY;
delete process.env.EPISODIC_MEMORY_ALLOW_METERED_API;
delete process.env.EPISODIC_MEMORY_API_BASE_URL;
delete process.env.EPISODIC_MEMORY_API_TOKEN;
delete process.env.EPISODIC_MEMORY_SUMMARY_TIMEOUT_MS;

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from 'fs';
import { join } from 'path';
import { tmpdir } from 'os';
import { findMissingDeps, REQUIRED_PACKAGES } from '../cli/install-check.js';

function stagePackage(nodeModules: string, name: string, manifest: object = { name, version: '0.0.0' }): void {
  const dir = join(nodeModules, name);
  mkdirSync(dir, { recursive: true });
  writeFileSync(join(dir, 'package.json'), JSON.stringify(manifest), 'utf-8');
}

describe('findMissingDeps — wrapper install-health probe (#95 Bug 1)', () => {
  let testDir: string;

  beforeEach(() => {
    testDir = mkdtempSync(join(tmpdir(), 'episodic-memory-install-check-'));
  });

  afterEach(() => {
    try { rmSync(testDir, { recursive: true, force: true }); } catch {}
  });

  it('returns the full required-packages list when node_modules is missing entirely', () => {
    const missing = findMissingDeps(testDir);
    expect(missing).toEqual([...REQUIRED_PACKAGES]);
  });

  it('returns the full list when node_modules is empty (recently-created folder)', () => {
    mkdirSync(join(testDir, 'node_modules'), { recursive: true });
    expect(findMissingDeps(testDir)).toEqual([...REQUIRED_PACKAGES]);
  });

  it('returns an empty list when every required package has a package.json', () => {
    const nodeModules = join(testDir, 'node_modules');
    mkdirSync(nodeModules, { recursive: true });
    for (const pkg of REQUIRED_PACKAGES) {
      stagePackage(nodeModules, pkg);
    }
    expect(findMissingDeps(testDir)).toEqual([]);
  });

  it('flags the partial-extraction case where a package directory exists but its package.json is missing (the reporter\'s exact failure on Windows 11)', () => {
    const nodeModules = join(testDir, 'node_modules');
    mkdirSync(nodeModules, { recursive: true });
    for (const pkg of REQUIRED_PACKAGES) {
      stagePackage(nodeModules, pkg);
    }
    // Simulate the bug from #95: better-sqlite3 directory exists with `deps/` and `LICENSE` but no package.json.
    const broken = join(nodeModules, 'better-sqlite3');
    rmSync(join(broken, 'package.json'));
    mkdirSync(join(broken, 'deps'), { recursive: true });
    writeFileSync(join(broken, 'LICENSE'), 'MIT', 'utf-8');

    expect(findMissingDeps(testDir)).toEqual(['better-sqlite3']);
  });

  it('returns multiple missing packages so the operator can see the full scope of damage in one log line', () => {
    const nodeModules = join(testDir, 'node_modules');
    mkdirSync(nodeModules, { recursive: true });
    // Only stage two of the required packages, leaving the rest missing.
    stagePackage(nodeModules, '@anthropic-ai/claude-agent-sdk');
    stagePackage(nodeModules, 'sqlite-vec');

    const missing = findMissingDeps(testDir);
    expect(missing).toContain('better-sqlite3');
    expect(missing).toContain('@huggingface/transformers');
    expect(missing).toContain('onnxruntime-node');
    expect(missing).not.toContain('@anthropic-ai/claude-agent-sdk');
    expect(missing).not.toContain('sqlite-vec');
  });

  it('treats a package npm nested under its dependent as installed, not missing (#105)', () => {
    const nodeModules = join(testDir, 'node_modules');
    mkdirSync(nodeModules, { recursive: true });
    for (const pkg of REQUIRED_PACKAGES) {
      stagePackage(nodeModules, pkg);
    }
    // Reproduce the real layout: a version conflict stops npm hoisting
    // onnxruntime-node, so it lands under @huggingface/transformers instead.
    rmSync(join(nodeModules, 'onnxruntime-node'), { recursive: true, force: true });
    stagePackage(
      join(nodeModules, '@huggingface', 'transformers', 'node_modules'),
      'onnxruntime-node'
    );

    // Node's resolver finds it there, so the wrapper must not reinstall on
    // every launch — that reinstall is what trips the 30s MCP connect timeout.
    expect(findMissingDeps(testDir)).toEqual([]);
  });

  it('still flags a nested package whose manifest is missing (partial extraction, one level down)', () => {
    const nodeModules = join(testDir, 'node_modules');
    mkdirSync(nodeModules, { recursive: true });
    for (const pkg of REQUIRED_PACKAGES) {
      stagePackage(nodeModules, pkg);
    }
    rmSync(join(nodeModules, 'onnxruntime-node'), { recursive: true, force: true });
    // Directory exists nested, but no package.json — same damage as #95.
    mkdirSync(
      join(nodeModules, '@huggingface', 'transformers', 'node_modules', 'onnxruntime-node'),
      { recursive: true }
    );

    expect(findMissingDeps(testDir)).toEqual(['onnxruntime-node']);
  });

  it('does not require optional / OS-specific deps (sharp, fsevents) — those are excluded by design', () => {
    const nodeModules = join(testDir, 'node_modules');
    mkdirSync(nodeModules, { recursive: true });
    for (const pkg of REQUIRED_PACKAGES) {
      stagePackage(nodeModules, pkg);
    }
    // sharp and fsevents are NOT staged — should still report no missing deps.
    expect(findMissingDeps(testDir)).toEqual([]);
    expect(REQUIRED_PACKAGES).not.toContain('sharp');
    expect(REQUIRED_PACKAGES).not.toContain('fsevents');
  });
});

import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { StdioClientTransport } from '@modelcontextprotocol/sdk/client/stdio.js';
import { existsSync, mkdirSync, mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const serverPath = fileURLToPath(new URL('../dist/mcp-server.js', import.meta.url));

function buildMcpTestEnv(root: string): Record<string, string> {
  return {
    HOME: join(root, 'home'),
    USERPROFILE: join(root, 'home'),
    XDG_CONFIG_HOME: join(root, 'xdg-config'),
    XDG_DATA_HOME: join(root, 'xdg-data'),
    EPISODIC_MEMORY_CONFIG_DIR: join(root, 'config'),
    TEST_DB_PATH: join(root, 'db.sqlite'),
    TEST_ARCHIVE_DIR: join(root, 'archive'),
    TEST_PROJECTS_DIR: join(root, 'projects'),
  };
}

it('builds an isolated MCP child environment', () => {
  const root = join(tmpdir(), 'episodic-memory-mcp-test');
  const previousDbPath = process.env.EPISODIC_MEMORY_DB_PATH;
  process.env.EPISODIC_MEMORY_DB_PATH = join(root, 'inherited-db.sqlite');
  try {
    const env = buildMcpTestEnv(root);
    expect(env).toMatchObject({
      HOME: join(root, 'home'),
      USERPROFILE: join(root, 'home'),
      EPISODIC_MEMORY_CONFIG_DIR: join(root, 'config'),
      TEST_DB_PATH: join(root, 'db.sqlite'),
      TEST_ARCHIVE_DIR: join(root, 'archive'),
      TEST_PROJECTS_DIR: join(root, 'projects'),
    });
    expect(env).not.toHaveProperty('EPISODIC_MEMORY_DB_PATH');
  } finally {
    if (previousDbPath === undefined) {
      delete process.env.EPISODIC_MEMORY_DB_PATH;
    } else {
      process.env.EPISODIC_MEMORY_DB_PATH = previousDbPath;
    }
  }
});

type ToolContent = { type: string; text?: string };

function getTextContent(content: ToolContent[]): string {
  const textItem = content.find((item) => item.type === 'text' && typeof item.text === 'string');
  expect(textItem?.text).toBeTruthy();
  return textItem!.text!;
}

describe('MCP search tool', () => {
  let client: Client;
  let transport: StdioClientTransport | undefined;
  let testDir: string | undefined;
  let testDbPath: string;

  beforeAll(async () => {
    testDir = mkdtempSync(join(tmpdir(), 'episodic-memory-mcp-'));
    testDbPath = join(testDir, 'db.sqlite');
    mkdirSync(join(testDir, 'archive'), { recursive: true });
    mkdirSync(join(testDir, 'projects'), { recursive: true });

    client = new Client({ name: 'episodic-memory-test', version: '1.0.0' }, { capabilities: {} });
    transport = new StdioClientTransport({
      command: process.execPath,
      args: [serverPath],
      stderr: 'pipe',
      env: buildMcpTestEnv(testDir),
    });
    await client.connect(transport);
  });

  afterAll(async () => {
    try {
      if (transport) {
        await transport.close();
      }
    } finally {
      if (testDir) {
        rmSync(testDir, { recursive: true, force: true });
      }
    }
  });

  it('advertises search and read tools with single and multi-concept queries', async () => {
    const tools = await client.listTools();
    const searchTool = tools.tools.find((tool) => tool.name === 'search');

    expect(searchTool).toBeDefined();
    expect(tools.tools.some((tool) => tool.name === 'read')).toBe(true);
    expect(searchTool?.inputSchema?.properties?.query).toMatchObject({
      oneOf: [
        { type: 'string', minLength: 2 },
        { type: 'array', minItems: 2, maxItems: 5 },
      ],
    });
  });

  it('accepts single-concept searches without using the user database', async () => {
    const result = await client.callTool({
      name: 'search',
      arguments: {
        query: 'isolated search query',
        mode: 'text',
        limit: 1,
        response_format: 'json',
      },
    });

    expect(result.isError).toBeFalsy();
    const payload = JSON.parse(getTextContent(result.content as ToolContent[]));
    expect(payload).toMatchObject({
      count: expect.any(Number),
      results: expect.any(Array),
      mode: 'text',
    });
    expect(existsSync(testDbPath)).toBe(true);
  });
});

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from 'fs';
import { join } from 'path';
import { tmpdir } from 'os';
import Database from 'better-sqlite3';
import { indexUnprocessed } from '../src/indexer.js';
import { searchConversations } from '../src/search.js';
import { suppressConsole } from './test-utils.js';

/**
 * Build one user/assistant exchange with controllable metadata fields so we
 * can verify filtering on them later. The exchange's text content embeds the
 * `topic` so semantic queries can find it.
 */
function makeExchangeLines(opts: {
  seq: number;
  sessionId: string;
  gitBranch: string;
  topic: string;
}): string {
  const { seq, sessionId, gitBranch, topic } = opts;
  const userUuid = `u-${seq}-${sessionId}`;
  const assistantUuid = `a-${seq}-${sessionId}`;
  const ts = new Date(2026, 0, 1 + seq).toISOString();
  const userLine = JSON.stringify({
    parentUuid: null,
    isSidechain: false,
    userType: 'external',
    cwd: '/test/project',
    sessionId,
    version: '2.0.9',
    gitBranch,
    type: 'user',
    message: { role: 'user', content: `Question about ${topic}` },
    uuid: userUuid,
    timestamp: ts,
  });
  const assistantLine = JSON.stringify({
    parentUuid: userUuid,
    isSidechain: false,
    userType: 'external',
    cwd: '/test/project',
    sessionId,
    version: '2.0.9',
    gitBranch,
    type: 'assistant',
    message: {
      model: 'claude-sonnet-4-5',
      role: 'assistant',
      content: [{ type: 'text', text: `Answer about ${topic}` }],
    },
    uuid: assistantUuid,
    timestamp: ts,
  });
  return userLine + '\n' + assistantLine + '\n';
}

describe('search metadata filters', () => {
  let testDir: string;
  let projectsDir: string;
  let archiveDir: string;
  let configDir: string;
  let dbPath: string;
  let restoreConsole: () => void;

  beforeEach(async () => {
    testDir = mkdtempSync(join(tmpdir(), 'em-meta-test-'));
    projectsDir = join(testDir, 'projects');
    archiveDir = join(testDir, 'archive');
    configDir = join(testDir, 'config');
    dbPath = join(testDir, 'test.db');
    mkdirSync(projectsDir, { recursive: true });
    mkdirSync(configDir, { recursive: true });

    process.env.TEST_PROJECTS_DIR = projectsDir;
    process.env.TEST_ARCHIVE_DIR = archiveDir;
    process.env.EPISODIC_MEMORY_CONFIG_DIR = configDir;
    process.env.TEST_DB_PATH = dbPath;
    restoreConsole = suppressConsole();

    // Seed: two projects with distinct sessions and branches discussing
    // overlapping topics.
    const projectA = join(projectsDir, 'project-a');
    const projectB = join(projectsDir, 'project-b');
    mkdirSync(projectA, { recursive: true });
    mkdirSync(projectB, { recursive: true });

    writeFileSync(
      join(projectA, 'session-1.jsonl'),
      makeExchangeLines({ seq: 1, sessionId: 'session-1', gitBranch: 'main', topic: 'authentication' }),
      'utf-8'
    );
    writeFileSync(
      join(projectA, 'session-2.jsonl'),
      makeExchangeLines({ seq: 2, sessionId: 'session-2', gitBranch: 'feature-x', topic: 'authentication' }),
      'utf-8'
    );
    writeFileSync(
      join(projectB, 'session-3.jsonl'),
      makeExchangeLines({ seq: 3, sessionId: 'session-3', gitBranch: 'main', topic: 'authentication' }),
      'utf-8'
    );

    await indexUnprocessed(1, true);
  });

  afterEach(() => {
    restoreConsole();
    delete process.env.TEST_PROJECTS_DIR;
    delete process.env.TEST_ARCHIVE_DIR;
    delete process.env.EPISODIC_MEMORY_CONFIG_DIR;
    delete process.env.TEST_DB_PATH;
    try { rmSync(testDir, { recursive: true, force: true }); } catch {}
  });

  it('filters search results by project name (exact match)', async () => {
    const results = await searchConversations('authentication', { project: 'project-a', mode: 'vector', limit: 10 });
    expect(results.length).toBeGreaterThan(0);
    for (const r of results) {
      expect(r.exchange.project).toBe('project-a');
    }
  });

  it('returns no results when project filter matches nothing', async () => {
    const results = await searchConversations('authentication', { project: 'project-nonexistent', mode: 'vector', limit: 10 });
    expect(results).toEqual([]);
  });

  it('filters by session_id (exact match)', async () => {
    const results = await searchConversations('authentication', { session_id: 'session-2', mode: 'text', limit: 10 });
    expect(results.length).toBeGreaterThan(0);
    // session-2 is in project-a only, so all archive paths point there
    for (const r of results) {
      expect(r.exchange.archivePath).toContain('project-a');
      expect(r.exchange.archivePath).toContain('session-2');
    }
  });

  it('filters by git_branch (exact match)', async () => {
    const results = await searchConversations('authentication', { git_branch: 'feature-x', mode: 'vector', limit: 10 });
    expect(results.length).toBeGreaterThan(0);
    // feature-x only exists on session-2 in project-a
    for (const r of results) {
      expect(r.exchange.archivePath).toContain('session-2');
    }
  });

  it('combines metadata filters with AND semantics', async () => {
    // project-a + main matches session-1 only
    const results = await searchConversations('authentication', {
      project: 'project-a',
      git_branch: 'main',
      mode: 'vector',
      limit: 10,
    });
    expect(results.length).toBeGreaterThan(0);
    for (const r of results) {
      expect(r.exchange.archivePath).toContain('session-1');
    }
  });

  it('rejects a single-quote in a filter value (no string-interpolation injection)', async () => {
    // With string interpolation this would either error with a SQL syntax issue
    // or, worse, succeed in injecting. With bound parameters it just doesn't match.
    const results = await searchConversations('authentication', {
      project: "project-a' OR '1'='1",
      mode: 'text',
      limit: 10,
    });
    expect(results).toEqual([]);
  });

  it('does not regress unfiltered search (returns all matching projects)', async () => {
    const results = await searchConversations('authentication', { mode: 'text', limit: 10 });
    const projects = new Set(results.map(r => r.exchange.project));
    expect(projects.has('project-a')).toBe(true);
    expect(projects.has('project-b')).toBe(true);
  });

  // #126 (via #128): date-filtered vector search used to return empty because vec0
  // ran KNN before the WHERE while k stayed at `limit`; #128 over-fetches (k = limit*3)
  // and applies after/before in the WHERE. This guards that after/before are honored in
  // vector mode; boundary and dates are derived from the fixture so it is timezone-robust.
  // (The exact large-index starvation #126 described needs a >limit fixture; #128's k=limit*3
  // is the fix.) Regression test contributed by @arimu1 (#133). --after/--before take YYYY-MM-DD.
  it('honors after/before date filters in vector search mode (#126)', async () => {
    const all = await searchConversations('authentication', { mode: 'vector', limit: 10 });
    expect(all.length).toBe(3);
    const dates = [...new Set(all.map(r => r.exchange.timestamp.slice(0, 10)))].sort();
    expect(dates.length).toBeGreaterThanOrEqual(2);
    const boundary = dates[1];

    const after = await searchConversations('authentication', { after: boundary, mode: 'vector', limit: 10 });
    expect(after.length).toBeGreaterThan(0);
    expect(after.length).toBeLessThan(all.length);
    for (const r of after) {
      expect(r.exchange.timestamp.slice(0, 10) >= boundary).toBe(true);
    }

    const before = await searchConversations('authentication', { before: boundary, mode: 'vector', limit: 10 });
    expect(before.length).toBeGreaterThan(0);
    for (const r of before) {
      expect(r.exchange.timestamp.slice(0, 10) <= boundary).toBe(true);
    }
  });
});

import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { mkdtempSync, rmSync, writeFileSync, mkdirSync } from 'fs';
import { join } from 'path';
import { tmpdir } from 'os';
import { initDatabase, insertExchange } from '../src/db.js';
import {
  buildTextMatchClause,
  escapeLikePattern,
  searchConversations,
  tokenizeTextQuery,
} from '../src/search.js';
import { ConversationExchange } from '../src/types.js';

describe('multi-word text search (#127)', () => {
  let testDir: string;
  const originalDbPath = process.env.TEST_DB_PATH;

  beforeEach(() => {
    testDir = mkdtempSync(join(tmpdir(), 'em-text-multiword-'));
    process.env.TEST_DB_PATH = join(testDir, 'index.sqlite');
  });

  afterEach(() => {
    if (originalDbPath === undefined) delete process.env.TEST_DB_PATH;
    else process.env.TEST_DB_PATH = originalDbPath;
    rmSync(testDir, { recursive: true, force: true });
  });

  function seedExchange(partial: Partial<ConversationExchange> & Pick<ConversationExchange, 'id' | 'userMessage' | 'assistantMessage'>): void {
    const archiveDir = join(testDir, 'archive');
    mkdirSync(archiveDir, { recursive: true });
    const archivePath = join(archiveDir, `${partial.id}.jsonl`);
    writeFileSync(archivePath, '{}\n', 'utf-8');

    const db = initDatabase();
    const exchange: ConversationExchange = {
      project: 'test-project',
      timestamp: '2026-05-12T20:00:00.000Z',
      lineStart: 1,
      lineEnd: 2,
      archivePath,
      harness: 'claude',
      sessionId: `session-${partial.id}`,
      ...partial,
    };
    insertExchange(db, exchange, new Array(384).fill(0.1));
    db.close();
  }

  it('tokenizes multi-word queries on whitespace', () => {
    expect(tokenizeTextQuery('date filter empty results')).toEqual([
      'date',
      'filter',
      'empty',
      'results',
    ]);
    expect(tokenizeTextQuery('  authentication   login  ')).toEqual([
      'authentication',
      'login',
    ]);
    expect(tokenizeTextQuery('single')).toEqual(['single']);
    expect(tokenizeTextQuery('   ')).toEqual([]);
  });

  it('escapes LIKE wildcards in patterns', () => {
    expect(escapeLikePattern('100%')).toBe('100\\%');
    expect(escapeLikePattern('a_b')).toBe('a\\_b');
    expect(escapeLikePattern('a\\b%')).toBe('a\\\\b\\%');
  });

  it('builds AND-ed per-token LIKE clauses', () => {
    const { sql, params } = buildTextMatchClause('authentication login');
    expect(sql).toBe(
      `(e.user_message LIKE ? ESCAPE '\\' OR e.assistant_message LIKE ? ESCAPE '\\')` +
        ` AND ` +
        `(e.user_message LIKE ? ESCAPE '\\' OR e.assistant_message LIKE ? ESCAPE '\\')`
    );
    expect(params).toEqual([
      '%authentication%',
      '%authentication%',
      '%login%',
      '%login%',
    ]);
  });

  it('matches multi-word queries when terms appear non-contiguously', async () => {
    // Repro from #127: words present but not as one contiguous substring.
    seedExchange({
      id: 'auth-login',
      userMessage: 'I fixed the authentication bug in the login flow',
      assistantMessage: 'Nice work on the fix.',
    });
    seedExchange({
      id: 'unrelated',
      userMessage: 'How do I configure logging only?',
      assistantMessage: 'Check the logging docs.',
    });

    const results = await searchConversations('authentication login', {
      mode: 'text',
      limit: 10,
    });

    const ids = results.map(r => r.exchange.id);
    expect(ids).toContain('auth-login');
    expect(ids).not.toContain('unrelated');
  });

  it('still matches a single-word query', async () => {
    seedExchange({
      id: 'single-hit',
      userMessage: 'Discussing authentication strategies',
      assistantMessage: 'Use OAuth.',
    });

    const results = await searchConversations('authentication', {
      mode: 'text',
      limit: 10,
    });

    expect(results.map(r => r.exchange.id)).toContain('single-hit');
  });

  it('requires every term (AND semantics) — missing term excludes the row', async () => {
    seedExchange({
      id: 'partial',
      userMessage: 'authentication only, no other keywords',
      assistantMessage: 'ok',
    });

    const results = await searchConversations('authentication login', {
      mode: 'text',
      limit: 10,
    });

    expect(results.map(r => r.exchange.id)).not.toContain('partial');
  });

  it('matches terms split across user and assistant messages', async () => {
    seedExchange({
      id: 'split-fields',
      userMessage: 'Please review the authentication changes',
      assistantMessage: 'The login path looks solid.',
    });

    const results = await searchConversations('authentication login', {
      mode: 'text',
      limit: 10,
    });

    expect(results.map(r => r.exchange.id)).toContain('split-fields');
  });

  it('treats % and _ in the query as literals, not LIKE wildcards', async () => {
    seedExchange({
      id: 'percent-literal',
      userMessage: 'Coverage is now 100% for the module',
      assistantMessage: 'Great.',
    });
    seedExchange({
      id: 'percent-false-positive',
      userMessage: 'Coverage is now 100X for the module',
      assistantMessage: 'Hmm.',
    });

    const results = await searchConversations('100%', {
      mode: 'text',
      limit: 10,
    });

    const ids = results.map(r => r.exchange.id);
    expect(ids).toContain('percent-literal');
    expect(ids).not.toContain('percent-false-positive');
  });
});

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from 'fs';
import { join } from 'path';
import { tmpdir } from 'os';
import { indexUnprocessed } from '../src/indexer.js';
import { searchConversations } from '../src/search.js';
import { suppressConsole } from './test-utils.js';

/**
 * Build one user/assistant exchange with a controllable `isSidechain` flag so
 * we can verify how subagent/workflow transcripts (which the harness records
 * with `isSidechain: true`) are treated by search. Content optionally embeds a
 * `topic` so semantic queries can find it, or an explicit user/assistant body
 * when the exact text matters (text-match contract tests).
 */
function makeExchangeLines(opts: {
  seq: number;
  sessionId: string;
  isSidechain: boolean;
  topic?: string;
  userText?: string;
  assistantText?: string;
}): string {
  const { seq, sessionId, isSidechain, topic } = opts;
  const userText = opts.userText ?? `Question about ${topic}`;
  const assistantText = opts.assistantText ?? `Answer about ${topic}`;
  const userUuid = `u-${seq}-${sessionId}`;
  const assistantUuid = `a-${seq}-${sessionId}`;
  const ts = new Date(2026, 0, 1 + seq).toISOString();
  const userLine = JSON.stringify({
    parentUuid: null,
    isSidechain,
    userType: 'external',
    cwd: '/test/project',
    sessionId,
    version: '2.0.9',
    gitBranch: 'main',
    type: 'user',
    message: { role: 'user', content: userText },
    uuid: userUuid,
    timestamp: ts,
  });
  const assistantLine = JSON.stringify({
    parentUuid: userUuid,
    isSidechain,
    userType: 'external',
    cwd: '/test/project',
    sessionId,
    version: '2.0.9',
    gitBranch: 'main',
    type: 'assistant',
    message: {
      model: 'claude-sonnet-4-5',
      role: 'assistant',
      content: [{ type: 'text', text: assistantText }],
    },
    uuid: assistantUuid,
    timestamp: ts,
  });
  return userLine + '\n' + assistantLine + '\n';
}

describe('search sidechain visibility', () => {
  let testDir: string;
  let projectsDir: string;
  let restoreConsole: () => void;

  beforeEach(() => {
    testDir = mkdtempSync(join(tmpdir(), 'em-sidechain-test-'));
    projectsDir = join(testDir, 'projects');
    mkdirSync(projectsDir, { recursive: true });
    mkdirSync(join(testDir, 'config'), { recursive: true });

    process.env.TEST_PROJECTS_DIR = projectsDir;
    process.env.TEST_ARCHIVE_DIR = join(testDir, 'archive');
    process.env.EPISODIC_MEMORY_CONFIG_DIR = join(testDir, 'config');
    process.env.TEST_DB_PATH = join(testDir, 'test.db');
    restoreConsole = suppressConsole();
  });

  afterEach(() => {
    restoreConsole();
    delete process.env.TEST_PROJECTS_DIR;
    delete process.env.TEST_ARCHIVE_DIR;
    delete process.env.EPISODIC_MEMORY_CONFIG_DIR;
    delete process.env.TEST_DB_PATH;
    try { rmSync(testDir, { recursive: true, force: true }); } catch {}
  });

  /** Write a project of session files and index them into a fresh DB. */
  async function seed(project: string, files: Record<string, string>): Promise<void> {
    const dir = join(projectsDir, project);
    mkdirSync(dir, { recursive: true });
    for (const [name, contents] of Object.entries(files)) {
      writeFileSync(join(dir, name), contents, 'utf-8');
    }
    await indexUnprocessed(1, true);
  }

  it('AC-1 (vector): finds a conversation whose substantive work ran in a subagent', async () => {
    // The only exchange discussing this topic is a sidechain (subagent) row.
    await seed('proj', {
      'sub.jsonl': makeExchangeLines({
        seq: 1, sessionId: 's-sub', isSidechain: true, topic: 'idempotent migration rollback strategy',
      }),
    });

    const results = await searchConversations('idempotent migration rollback strategy', {
      mode: 'vector', limit: 10,
    });

    expect(results.length).toBeGreaterThan(0);
    expect(results.some(r => r.exchange.isSidechain)).toBe(true);
  });

  it('AC-1 (text): finds subagent work via exact text search', async () => {
    await seed('proj', {
      'sub.jsonl': makeExchangeLines({
        seq: 1, sessionId: 's-sub', isSidechain: true, topic: 'idempotent migration rollback strategy',
      }),
    });

    const results = await searchConversations('idempotent migration rollback strategy', {
      mode: 'text', limit: 10,
    });

    expect(results.length).toBeGreaterThan(0);
    expect(results.some(r => r.exchange.isSidechain)).toBe(true);
  });

  it('include_sidechains: false restores the old behavior (excludes sidechains)', async () => {
    await seed('proj', {
      'sub.jsonl': makeExchangeLines({
        seq: 1, sessionId: 's-sub', isSidechain: true, topic: 'idempotent migration rollback strategy',
      }),
    });

    const vector = await searchConversations('idempotent migration rollback strategy', {
      mode: 'vector', limit: 10, include_sidechains: false,
    });
    const text = await searchConversations('idempotent migration rollback strategy', {
      mode: 'text', limit: 10, include_sidechains: false,
    });

    expect(vector).toEqual([]);
    expect(text).toEqual([]);
  });

  it('de-ranks sidechains below equally-relevant main-thread rows (vector)', async () => {
    // Identical content in two files: same embedding, same distance to the
    // query, so ordering is decided purely by the sidechain de-rank penalty.
    const body = { topic: 'connection pool exhaustion under load' };
    await seed('proj', {
      'main.jsonl': makeExchangeLines({ seq: 1, sessionId: 's-main', isSidechain: false, ...body }),
      'sub.jsonl': makeExchangeLines({ seq: 2, sessionId: 's-sub', isSidechain: true, ...body }),
    });

    const results = await searchConversations('connection pool exhaustion under load', {
      mode: 'vector', limit: 10,
    });

    expect(results.length).toBe(2);
    expect(results[0].exchange.isSidechain).toBe(false);
    expect(results[1].exchange.isSidechain).toBe(true);
  });

  it('de-ranks sidechains below main-thread rows (text)', async () => {
    const body = { topic: 'connection pool exhaustion under load' };
    await seed('proj', {
      'main.jsonl': makeExchangeLines({ seq: 1, sessionId: 's-main', isSidechain: false, ...body }),
      'sub.jsonl': makeExchangeLines({ seq: 2, sessionId: 's-sub', isSidechain: true, ...body }),
    });

    const results = await searchConversations('connection pool exhaustion under load', {
      mode: 'text', limit: 10,
    });

    expect(results.length).toBe(2);
    expect(results[0].exchange.isSidechain).toBe(false);
    expect(results[1].exchange.isSidechain).toBe(true);
  });

  it('returns both main-thread and sidechain rows by default', async () => {
    await seed('proj', {
      'main.jsonl': makeExchangeLines({ seq: 1, sessionId: 's-main', isSidechain: false, topic: 'retry backoff jitter' }),
      'sub.jsonl': makeExchangeLines({ seq: 2, sessionId: 's-sub', isSidechain: true, topic: 'retry backoff jitter' }),
    });

    const results = await searchConversations('retry backoff jitter', { mode: 'both', limit: 10 });
    const kinds = new Set(results.map(r => r.exchange.isSidechain));
    expect(kinds.has(false)).toBe(true);
    expect(kinds.has(true)).toBe(true);
  });

  // AC-3: pin the text path's matching contract as it ships — the whole query
  // is matched as one contiguous, case-insensitive substring (no tokenization).
  // Text search is a multi-word AND of per-token LIKEs (#144): a query matches
  // when every word appears somewhere in the exchange, in any order. This
  // supersedes the older whole-query "contiguous substring" contract.
  describe('text-match contract (multi-word AND of tokens, #144)', () => {
    beforeEach(async () => {
      await seed('proj', {
        's.jsonl': makeExchangeLines({
          seq: 1, sessionId: 's-1', isSidechain: false,
          userText: 'We tuned the alpha beta gamma delta pipeline today',
          assistantText: 'Noted the pipeline change.',
        }),
      });
    });

    it('matches when all query words are present (contiguous order)', async () => {
      const results = await searchConversations('alpha beta gamma', { mode: 'text', limit: 10 });
      expect(results.length).toBe(1);
    });

    it('matches regardless of word order — tokens are AND-ed, not a substring (#144)', async () => {
      const results = await searchConversations('gamma alpha beta', { mode: 'text', limit: 10 });
      expect(results.length).toBe(1);
    });

    it('does not match when the query includes a word absent from the run', async () => {
      const results = await searchConversations('alpha beta epsilon gamma', { mode: 'text', limit: 10 });
      expect(results).toEqual([]);
    });
  });
});

