#!/usr/bin/env node
/**
 * Cross-platform wrapper script for MCP server that ensures dependencies are installed
 * This runs before the MCP server starts and works on Windows, macOS, and Linux
 */

import { spawn } from 'child_process';
import { existsSync } from 'fs';
import { dirname, join } from 'path';
import { fileURLToPath } from 'url';
import { findMissingDeps } from './install-check.js';
import { acquireInstallLock, runNpmInstall, waitForInstallLock } from './install-runner.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// Determine plugin root directory
const PLUGIN_ROOT = process.env.CLAUDE_PLUGIN_ROOT || join(__dirname, '..');

async function main() {
  try {
    // Probe each required runtime dependency's package.json — not just the
    // node_modules directory. A partial extraction (folder exists but the
    // package is missing its manifest and lib/) would slip past an existsSync
    // check on node_modules alone and crash the server with ERR_MODULE_NOT_FOUND
    // *after* the wrapper has handed off to dist/mcp-server.js (#95 Bug 1).
    const missing = findMissingDeps(PLUGIN_ROOT);
    if (missing.length > 0) {
      console.error(`Missing dependencies under node_modules: ${missing.join(', ')}`);

      // Single-flight: a second wrapper launched while one is already
      // installing must not start a competing install (#161) — repeated
      // wrapper launches within the client's connect-timeout window would
      // otherwise stack unbounded concurrent `npm install`s.
      const lock = acquireInstallLock(PLUGIN_ROOT);
      if (lock) {
        const install = runNpmInstall(PLUGIN_ROOT, { lockHandle: lock });
        await install.promise;
      } else {
        console.error('Another install is already in progress; waiting for it to finish...');
        await waitForInstallLock(PLUGIN_ROOT);
        // Re-probe: the other install may have completed the deps by now.
        const stillMissing = findMissingDeps(PLUGIN_ROOT);
        if (stillMissing.length > 0) {
          console.error(`Still missing after waiting: ${stillMissing.join(', ')}. Continuing anyway.`);
        }
      }
    }

    // Start the MCP server
    const mcpServerPath = join(PLUGIN_ROOT, 'dist', 'mcp-server.js');

    if (!existsSync(mcpServerPath)) {
      console.error(`ERROR: MCP server not found at ${mcpServerPath}`);
      console.error('Please run: npm run build');
      process.exit(1);
    }

    // Use spawn with shell: false for better cross-platform compatibility
    const child = spawn(process.execPath, [mcpServerPath], {
      stdio: 'inherit',
      shell: false
    });

    // Forward signals to the child process
    process.on('SIGTERM', () => child.kill('SIGTERM'));
    process.on('SIGINT', () => child.kill('SIGINT'));
    process.on('SIGHUP', () => child.kill('SIGHUP'));

    // Detect parent process death via stdin close
    // When Claude exits (normally or abnormally), stdin will close
    process.stdin.on('end', () => {
      child.kill();
      process.exit(0);
    });

    child.on('exit', (code, signal) => {
      if (signal) {
        process.kill(process.pid, signal);
      } else {
        process.exit(code || 0);
      }
    });

    child.on('error', (err) => {
      console.error(`ERROR: Failed to start MCP server: ${err.message}`);
      process.exit(1);
    });

  } catch (error) {
    console.error(`ERROR: ${error.message}`);
    process.exit(1);
  }
}

main().catch((error) => {
  console.error(`Unexpected error: ${error.message}`);
  process.exit(1);
});

import { searchConversations, formatResults, searchMultipleConcepts, formatMultiConceptResults, SearchOptions } from './search.js';

const args = process.argv.slice(2);

// Parse arguments
let mode: 'vector' | 'text' | 'both' = 'both';
let after: string | undefined;
let before: string | undefined;
let project: string | undefined;
let sessionId: string | undefined;
let gitBranch: string | undefined;
let includeSidechains = true;
let limit = 10;
const queries: string[] = [];

for (let i = 0; i < args.length; i++) {
  const arg = args[i];

  if (arg === '--help' || arg === '-h') {
    console.log(`
Usage: episodic-memory search [OPTIONS] <query>

Search indexed conversations using semantic similarity or exact text matching.

MODES:
  (default)      Combined vector + text search
  --vector       Vector similarity only (semantic)
  --text         Exact substring matching only (whole query matched verbatim;
                 best for git SHAs, error codes — not natural language)

OPTIONS:
  --after DATE          Only conversations after YYYY-MM-DD
  --before DATE         Only conversations before YYYY-MM-DD
  --project NAME        Filter by project name (exact match)
  --session-id ID       Filter by session ID (exact match)
  --git-branch BRANCH   Filter by git branch name (exact match)
  --exclude-sidechains  Search only the main thread; omit subagent/workflow
                        conversations (included and de-ranked by default)
  --limit N             Max results (default: 10)
  --help, -h            Show this help

EXAMPLES:
  # Semantic search
  episodic-memory search "React Router authentication errors"

  # Find exact string
  episodic-memory search --text "a1b2c3d4e5f6"

  # Time filtering
  episodic-memory search --after 2025-09-01 "refactoring"

  # Filter to one project
  episodic-memory search --project my-app "auth flow"

  # Filter to one git branch
  episodic-memory search --git-branch feature/login "validation"

  # Combine modes
  episodic-memory search --both "React Router data loading"

  # Multi-concept search (AND - all concepts must match)
  episodic-memory search "React Router" "authentication" "JWT"
`);
    process.exit(0);
  } else if (arg === '--vector') {
    mode = 'vector';
  } else if (arg === '--text') {
    mode = 'text';
  } else if (arg === '--after') {
    after = args[++i];
  } else if (arg === '--before') {
    before = args[++i];
  } else if (arg === '--project') {
    project = args[++i];
  } else if (arg === '--session-id') {
    sessionId = args[++i];
  } else if (arg === '--git-branch') {
    gitBranch = args[++i];
  } else if (arg === '--exclude-sidechains') {
    includeSidechains = false;
  } else if (arg === '--limit') {
    limit = parseInt(args[++i]);
  } else {
    // All non-flag args are query terms
    queries.push(arg);
  }
}

if (queries.length === 0) {
  console.error('Usage: episodic-memory search [OPTIONS] <query> [query2] [query3]...');
  console.error('Try: episodic-memory search --help');
  process.exit(1);
}

// Multi-concept search if multiple queries provided
if (queries.length > 1) {
  const options = { limit, after, before, project, session_id: sessionId, git_branch: gitBranch, include_sidechains: includeSidechains };

  searchMultipleConcepts(queries, options)
    .then(async results => {
      console.log(await formatMultiConceptResults(results, queries));
    })
    .catch(error => {
      console.error('Error searching:', error);
      process.exit(1);
    });
} else {
  // Single query - use regular search
  const options: SearchOptions = {
    mode,
    limit,
    after,
    before,
    project,
    session_id: sessionId,
    git_branch: gitBranch,
    include_sidechains: includeSidechains,
  };

  searchConversations(queries[0], options)
    .then(async results => {
      console.log(await formatResults(results));
    })
    .catch(error => {
      console.error('Error searching:', error);
      process.exit(1);
    });
}

#!/usr/bin/env node
/**
 * MCP Server for Episodic Memory.
 *
 * This server provides tools to search and explore indexed Claude Code, Codex, and opencode conversations
 * using semantic search, text search, and conversation display capabilities.
 */

import { Server } from '@modelcontextprotocol/sdk/server/index.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import {
  CallToolRequestSchema,
  ListToolsRequestSchema,
} from '@modelcontextprotocol/sdk/types.js';
import { z } from 'zod';
import {
  searchConversations,
  searchMultipleConcepts,
  formatResults,
  formatMultiConceptResults,
  SearchOptions,
} from './search.js';
import { formatConversationAsMarkdown } from './show.js';
import { VERSION } from './version.js';
import fs from 'fs';

// Zod Schemas for Input Validation

const SearchModeEnum = z.enum(['vector', 'text', 'both']);
const ResponseFormatEnum = z.enum(['markdown', 'json']);

const SearchInputSchema = z
  .object({
    query: z
      .union([
        z.string().min(2, 'Query must be at least 2 characters'),
        z
          .array(z.string().min(2))
          .min(2, 'Must provide at least 2 concepts for multi-concept search')
          .max(5, 'Cannot search more than 5 concepts at once'),
      ])
      .describe(
        'Search query - string for single concept, array of strings for multi-concept AND search'
      ),
    mode: SearchModeEnum.default('both').describe(
      'Search mode: "vector" for semantic similarity, "text" for exact matching, "both" for combined (default: "both"). Only used for single-concept searches.'
    ),
    limit: z
      .number()
      .int()
      .min(1)
      .max(50)
      .default(10)
      .describe('Maximum number of results to return (default: 10)'),
    after: z
      .string()
      .regex(/^\d{4}-\d{2}-\d{2}$/, 'Date must be in YYYY-MM-DD format')
      .optional()
      .describe('Only return conversations after this date (YYYY-MM-DD format)'),
    before: z
      .string()
      .regex(/^\d{4}-\d{2}-\d{2}$/, 'Date must be in YYYY-MM-DD format')
      .optional()
      .describe('Only return conversations before this date (YYYY-MM-DD format)'),
    project: z
      .string()
      .min(1)
      .optional()
      .describe('Filter by project name (exact match)'),
    session_id: z
      .string()
      .min(1)
      .optional()
      .describe('Filter by session ID (exact match)'),
    git_branch: z
      .string()
      .min(1)
      .optional()
      .describe('Filter by git branch name (exact match)'),
    include_sidechains: z
      .boolean()
      .default(true)
      .describe(
        'Include subagent/workflow (sidechain) conversations, de-ranked below main-thread matches (default: true). Set false to search only the main thread.'
      ),
    response_format: ResponseFormatEnum.default('markdown').describe(
      'Output format: "markdown" for human-readable or "json" for machine-readable (default: "markdown")'
    ),
  })
  .strict();

type SearchInput = z.infer<typeof SearchInputSchema>;

const ShowConversationInputSchema = z
  .object({
    path: z
      .string()
